class ClasseRepository extends \Doctrine\ORM\EntityRepository {

    public function classe_echelon() {
        $qb = $this->createQueryBuilder('c')
                ->join('c.Grade', 'g')
                ->addSelect('g');
        return $qb->getQuery()->getResult();
    }

    public function enattente_affectation($type = null) {
        $critere = $parameter = null;

        $qb = $this->getEntityManager()->createQueryBuilder()
                ->select("aff ")
                ->from('AgentBundle:Affecter', 'aff')
                ->where('1 = 1');

        switch ($type) {
            //Personne en attente d’affectation depuis un mois
            case 'affectation_no': {
                    $critere = $qb->andWhere('aff.etatAffectation = :etataffectation')
                            ->andWhere('TIMESTAMPDIFF(MONTH, aff.dateEnregAgt, CURRENT_TIMESTAMP()) >= :datecreation ');

                    $parameter = $qb->setParameter('etataffectation', 0)
                            ->setParameter('datecreation', 1);
                } break;
            //Personnes affecter dans un service et n’ayant pas encore pris service depuis 1 semaine
            case 'affectation_yes': {
                    $critere = $qb->andWhere('aff.etatAffectation >= :etataffectation')
                            ->andWhere('TIMESTAMPDIFF(WEEK, aff.dateMiseService, CURRENT_TIMESTAMP()) >= :dateMiseService ')
                            ->andWhere("aff.dateprise is null Or aff.dateprise = '' ");

                    $parameter = $qb->setParameter('etataffectation', 1)
                            ->setParameter('dateMiseService', 1);
                } break;
            //Personnes ayant pris service et en attente de signature du certficat depuis 1 semaine
            case 'certificat': {
                    $critere = $qb->andWhere('aff.etatAffectation >= :etataffectation')
                            ->andWhere("aff.dateprise is not null and aff.dateprise <> '' ")
                            ->andWhere("aff.signeCertificat = :signeCertificat ")
                            ->andWhere('TIMESTAMPDIFF(WEEK, aff.dateprise, CURRENT_TIMESTAMP()) >= :dateprise ');

                    $parameter = $qb->setParameter('etataffectation', 1)
                            ->setParameter('signeCertificat', 0)
                            ->setParameter('dateprise', 1);
                } break;
        }

        $qb = $critere;
        $qb = $parameter;
//dump($qb->getQuery());die;
        return $qb->getQuery()->getResult();
    }

     public function statsgrade($all = null, $demembrement = null) {
        $qb = $this->getEntityManager()->createQueryBuilder();
        $d="";
        if ($demembrement != null) {           
            foreach ($demembrement as $value) {
                $x = substr($value, 0, 2);
                if ($x == 'SC') {
                    $d= $d." And agent.code_sc = '".$value."' ";
                }
                if ($x == 'SD') {
                    $d= $d." And agent.code_sd = '".$value."' ";
                }
                if ($x == 'DC') {
                    $d= $d." And agent.code_dc = '".$value."' ";
                }
                if ($x == 'DG') {
                    $d= $d." And agent.code_dg = '".$value."' ";
                }
            }
        }

        switch ($all) {
            //grade
            case 1: $qb = $qb->select("grade.libGrade as lib, sum(case when agent.Sexe = 1 then 1 else 0 end) as m,
                  sum(case when agent.Sexe = 2 then 1 else 0 end) as f, count(agent.Sexe) as total  ")
                        ->groupBy('grade.libGrade')
                        ->orderBy('grade.libGrade', 'ASC');
                break;
//categorie
            case 2: $qb = $qb->select("Left(grade.libGrade, 1) as lib, sum(case when agent.Sexe = 1 then 1 else 0 end) as m,
                  sum(case when agent.Sexe = 2 then 1 else 0 end) as f, count(agent.Sexe) as total  ")
                        ->groupBy('lib')
                        ->orderBy('lib', 'ASC');
                break;
//effectif general
            case 3: $qb = $qb->select("sum(case when agent.Sexe = 1 then 1 else 0 end) as m,
                  sum(case when agent.Sexe = 2 then 1 else 0 end) as f, count(agent.Sexe) as total,
                  sum(case when (agent.Type = 1 and agent.Sexe = 1) Then 1 else 0 end) as fonctionnairehomme,
                  sum(case when (agent.Type = 1 and agent.Sexe = 2) Then 1 else 0 end) as fonctionnairefemme,
                  sum(case when (agent.Type = 1) Then 1 else 0 end) as fonctionnairetotal,
                  sum(case when (agent.Type = 2 and agent.Sexe = 1) Then 1 else 0 end) as contractuelhomme,
                  sum(case when (agent.Type = 2 and agent.Sexe = 2) Then 1 else 0 end) as contractuelfemme,
                  sum(case when (agent.Type = 2) Then 1 else 0 end) as contractueltotal ")
                        //->groupBy('agent.Sexe, agent.Type')
                        ->orderBy('agent.Sexe', 'ASC');
                break;
//emploi
            case 4: $qb = $qb->select("emploi.libEmpl as lib, sum(case when agent.Sexe = 1 then 1 else 0 end) as m,
                  sum(case when agent.Sexe = 2 then 1 else 0 end) as f, count(agent.Sexe) as total,
                  sum(case when (agent.Type = 1 and agent.Sexe = 1) Then 1 else 0 end) as fonctionnairehomme,
                  emploi.id")
                        ->groupBy('emploi.libEmpl')
                        ->orderBy('emploi.libEmpl', 'ASC');
                break;
//direction
            case 5: $qb = $qb->select("direction.libDirect as lib, sum(case when agent.Sexe = 1 then 1 else 0 end) as m,
                  sum(case when agent.Sexe = 2 then 1 else 0 end) as f, count(agent.Sexe) as total,
                  sum(case when (agent.Type = 1 and agent.Sexe = 1) Then 1 else 0 end) as fonctionnairehomme,
                  sum(case when (agent.Type = 1 and agent.Sexe = 2) Then 1 else 0 end) as fonctionnairefemme,
                  sum(case when (agent.Type = 1) Then 1 else 0 end) as fonctionnairetotal,
                  sum(case when (agent.Type = 2 and agent.Sexe = 1) Then 1 else 0 end) as contractuelhomme,
                  sum(case when (agent.Type = 2 and agent.Sexe = 2) Then 1 else 0 end) as contractuelfemme,
                  sum(case when (agent.Type = 2) Then 1 else 0 end) as contractueltotal,
                  direction.id")
                        ->groupBy('direction.libDirect')
                        ->orderBy('direction.libDirect', 'ASC');
                break;

            //direction par emploi
            case 6: $qb = $qb->select("direction.libDirect as lib, emploi.libEmpl, sum(case when agent.Sexe = 1 then 1 else 0 end) as m,
                  sum(case when agent.Sexe = 2 then 1 else 0 end) as f, count(agent.Sexe) as total,
                  sum(case when (agent.Type = 1 and agent.Sexe = 1) Then 1 else 0 end) as fonctionnairehomme,
                  sum(case when (agent.Type = 1 and agent.Sexe = 2) Then 1 else 0 end) as fonctionnairefemme,
                  sum(case when (agent.Type = 1) Then 1 else 0 end) as fonctionnairetotal,
                  sum(case when (agent.Type = 2 and agent.Sexe = 1) Then 1 else 0 end) as contractuelhomme,
                  sum(case when (agent.Type = 2 and agent.Sexe = 2) Then 1 else 0 end) as contractuelfemme,
                  sum(case when (agent.Type = 2) Then 1 else 0 end) as contractueltotal,
                  direction.id as iddirection  ")
                        ->groupBy('direction.libDirect, emploi.libEmpl')
                        ->orderBy('direction.libDirect, emploi.libEmpl', 'ASC');
                break;

            //par syndicat
            case 7: $qb = $qb->select("Syndicat.libSynd, sum(case when agent.Sexe = 1 then 1 else 0 end) as m,
                  sum(case when agent.Sexe = 2 then 1 else 0 end) as f, count(agent.Sexe) as total  ")
                        ->groupBy('Syndicat.libSynd')
                        ->orderBy('Syndicat.libSynd', 'ASC');
                break;
        }


        $qb = $qb->from('AgentBundle:Agent', 'agent')
                ->innerJoin('AgentBundle:Emploi', 'emploi', Join::WITH, 'agent.Emploi = emploi.id')
                ->innerJoin('AgentBundle:Grade', 'grade', Join::WITH, 'emploi.Grade = grade.id')
                ->innerJoin('AgentBundle:Direction', 'direction', Join::WITH, 'agent.Direction = direction.id')
                ->LeftJoin('AgentBundle:Syndicat', 'Syndicat', Join::WITH, 'agent.Syndicat = Syndicat.id')
                ->where('1 = 1 '.$d )
                ->andWhere('agent.position is null or agent.position = 0');

        return $qb->getQuery()->getResult();
    }

